WITH flattened AS (SELECT id, service, log_ts, level, status_code, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, value) SELECT level, CASE WHEN status_code >= 470 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, AVG(status_code) FILTER (WHERE k = 'trace') AS trace_avg_status_code, ROUND(AVG(status_code), 2) AS avg_status_code FROM flattened GROUP BY level, CASE WHEN status_code >= 470 THEN 'HIGH' ELSE 'LOW' END ORDER BY level DESC NULLS FIRST
